 v:[["周末","zhōumò","วันหยุดสุดสัปดาห์","ທ້າຍອາທິດ"],["打算","dǎsuàn","ตั้งใจ, วางแผน","ຕັ້ງໃຈ, ວາງແຜນ"],["爬山","pá shān","ปีนเขา","ປີນພູ"],["公园","gōngyuán","สวนสาธารณะ","ສວນສາທາລະນະ"],["或者","huòzhě","หรือ (ประโยคบอกเล่า)","ຫຼື"],["还是","háishi","หรือ (ประโยคคำถาม)","ຫຼື (ຄຳຖາມ)"],["参加","cānjiā","เข้าร่วม","ເຂົ້າຮ່ວມ"],["比赛","bǐsài","การแข่งขัน","ການແຂ່ງຂັນ"],["体育","tǐyù","กีฬา, พลศึกษา","ກິລາ, ພະລະສຶກສາ"],["锻炼","duànliàn","ออกกำลังกาย, ฝึกฝน","ອອກກຳລັງກາຍ"]],
