 v:[["结婚","jiéhūn","แต่งงาน","ແຕ່ງງານ"],["节日","jiérì","เทศกาล","ບຸນ, ເທດສະການ"],["礼物","lǐwù","ของขวัญ","ຂອງຂວັນ"],["客人","kèrén","แขก","ແຂກ"],["见面","jiànmiàn","พบกัน","ພົບກັນ"],["满意","mǎnyì","พอใจ","ພໍໃຈ"],["愿意","yuànyì","ยินดี, เต็มใจ","ເຕັມໃຈ"],["当然","dāngrán","แน่นอน","ແນ່ນອນ"]],
 g:[{t:"跟 + คน + 见面 = พบกับ...",n:"见面 ไม่ตามด้วยคนโดยตรง ต้องใช้ 跟 นำหน้า",e:[["我明天跟他见面。","Wǒ míngtiān gēn tā jiànmiàn.","พรุ่งนี้ฉันจะเจอกับเขา"]]},
   {t:"愿意 + กริยา = ยินดี...",n:"บอกความเต็มใจ",e:[["你愿意跟我结婚吗？","Nǐ yuànyì gēn wǒ jiéhūn ma?","คุณจะแต่งงานกับฉันไหม"],["我愿意帮助你。","Wǒ yuànyì bāngzhù nǐ.","ฉันยินดีช่วยคุณ"]]},
   {t:"当然 = แน่นอน",n:"ใช้ตอบรับอย่างหนักแน่น",e:[["当然可以！","Dāngrán kěyǐ!","ได้แน่นอน"]]},
   {t:"对 + … + 很满意 = พอใจ...",n:"บอกว่าพอใจกับอะไร",e:[["客人对这个礼物很满意。","Kèrén duì zhège lǐwù hěn mǎnyì.","แขกพอใจกับของขวัญชิ้นนี้มาก"]]}],
 d:[["A","下个月我姐姐结婚。","Xià ge yuè wǒ jiějie jiéhūn.","เดือนหน้าพี่สาวฉันจะแต่งงาน"],["B","太好了！你打算送什么礼物？","Tài hǎo le! Nǐ dǎsuàn sòng shénme lǐwù?","ดีจังเลย คุณจะให้ของขวัญอะไร"],["A","还没想好。你愿意跟我一起去买吗？","Hái méi xiǎng hǎo. Nǐ yuànyì gēn wǒ yìqǐ qù mǎi ma?","ยังคิดไม่ออกเลย ไปซื้อด้วยกันไหม"],["B","当然！我们明天下午见面吧。","Dāngrán! Wǒmen míngtiān xiàwǔ jiànmiàn ba.","แน่นอน พรุ่งนี้บ่ายเจอกันนะ"],["A","好！希望姐姐会满意。","Hǎo! Xīwàng jiějie huì mǎnyì.","ได้ หวังว่าพี่สาวจะพอใจ"]],
